INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 11, 'theory', 'Квиз: бонд, MTU и ethtool');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 11, 0, 'В бонде стоит miimon 100, и вы задали downdelay 250. Сколько миллисекунд после обнаружения потери несущей драйвер будет ждать, прежде чем объявить ведомый интерфейс упавшим?', '["250", "100", "200", "300"]', 2, 'Задержки считаются в периодах опроса, поэтому значение округляется вниз до кратного miimon: 250 превращается в 200. Лучше сразу задавать кратные значения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 11, 1, 'Что значит пометка [fixed] рядом с разгрузкой в выводе ethtool -k?', '["Драйвер или карта не позволяют изменить эту разгрузку", "Разгрузка включена навсегда, а выключена быть не может", "Изменение запрошено, но ещё не применено", "Разгрузка зафиксирована в конфигурации NetworkManager"]', 0, 'Пометка [fixed] ставится, когда у карты нет такой возможности или её нельзя менять; значение может быть и on, и off. Запрошенное, но не применённое изменение выглядит как [requested on] или [requested off].');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 11, 2, 'Почему политика layer3+4 не даёт одному TCP-соединению скорость двух интерфейсов бонда?', '["Порты в хеше не учитываются", "Она работает только для UDP", "Хеш считается заново для каждого пакета", "Хеш одного соединения постоянен, поэтому оно всегда идёт по одному интерфейсу"]', 3, 'Адреса и порты соединения не меняются, значит, не меняется и результат хеша. Разные соединения расходятся, но одно остаётся на своём интерфейсе. Только balance-rr раскладывает одно соединение по интерфейсам, ценой перестановки пакетов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 11, 3, 'Какое наибольшее значение -s пройдёт командой ping -M do -s N по IPv4-каналу с MTU 1500?', '["1500", "1472", "1464", "1450"]', 1, 'К данным ping добавляются 8 байт заголовка ICMP и 20 байт заголовка IPv4, всего 28. Поэтому 1500 минус 28 равно 1472; со значением 1473 ядро ответит message too long.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 11, 4, 'В бонде 802.3ad у одного ведомого Aggregator ID не совпадает с активным агрегатом, а MAC партнёра нулевой. Что вероятнее всего?', '["Слишком большой miimon", "Выбрана политика layer2", "Коммутатор не ведёт LACP на этом порту: он не в том канале или LACP выключен", "Слишком короткий updelay"]', 2, 'Нулевой MAC партнёра означает, что LACPDU от соседа не приходят, и порт собран в одиночный агрегат. Причина обычно на стороне коммутатора или в кабеле; miimon и хеш на это не влияют.');
